        final double METRES_PER_MILE = 1609.344;   // final: never reassigned.
        double miles = 3.5;                         // measurement: double.
        double metres = miles * METRES_PER_MILE;    // 5632.704

        long raw = 42L;                             // e.g. parsed from input.
        if (raw < 0 || raw > Integer.MAX_VALUE) throw new IllegalArgumentException("bad count");
        int items = (int) raw;                      // exact count, range checked first.

        boolean shipped = false;
        char grade = 'A';
        long bigTotal = 3_000_000_000L;             // too big for int.
        System.out.println(metres + " " + items + " " + bigTotal);
        System.out.println(Integer.MAX_VALUE + 1);  // -2147483648: silent overflow.
    }
}
